def calculate_S(N):
    S_N = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S_N += (a * b) // (N + 1)
    return S_N

def calculate_T(N):
    return (N**3 - N**2 + 2) / 4

results = {}
for N in range(1, 6):
    S_N = calculate_S(N)
    T_N = calculate_T(N)
    results[N] = {
        "S(N)": S_N,
        "Target T(N)": T_N,
        "Match": S_N == T_N
    }

print("--- Results for N=1 to 5 ---")
for N, res in results.items():
    print(f"N = {N}:")
    print(f"  S({N}) = {res['S(N)']}")
    print(f"  Target T({N}) = {res['Target T(N)']}")
    print(f"  Match? {res['Match']}")

def calculate_S(N):
    M = N + 1
    S = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // M
    return S

def calculate_T(N):
    return (N**3 - N**2 + 2) / 4

N_values = [1, 2, 3, 4, 5]
results = {}
for N in N_values:
    S_N = calculate_S(N)
    T_N = calculate_T(N)
    results[N] = {'S': S_N, 'T': T_N, 'Match': S_N == T_N}

for N, res in results.items():
    print(f"N={N}: S(N)={res['S']}, T(N)={res['T']}, Match={res['Match']}")

